import {Component,OnInit,OnDestroy} from '@angular/core';import {CommonModule} from '@angular/common';import {FormsModule} from '@angular/forms';import {RouterModule} from '@angular/router';import {HttpClient} from '@angular/common/http';import {firstValueFrom,Subscription} from 'rxjs';import {ReservationAuthService} from '../services/reservation-auth.service';import {LanguageService} from '../services/language.service';import {PlatformLayoutComponent} from '../layout/platform-layout/platform-layout.component';
@Component({standalone:true,imports:[CommonModule,FormsModule,RouterModule,PlatformLayoutComponent],templateUrl:'./legal-admin.component.html',styleUrls:['./legal-admin.component.scss']})
export class LegalAdminComponent implements OnInit,OnDestroy{
 data:any;role='customer';lang='fr';document:any={};file?:File;reviewed=false;confirmed=false;busy=false;error='';message='';readonly roles=['customer','assetOwner','concierge'];readonly languages=['fr','en','es','it','de','nl','ru'];private sub?:Subscription;private uid='';private sequence=0;private editor=0;private base='/api/platform/admin/legal';
 constructor(private http:HttpClient,private auth:ReservationAuthService,public language:LanguageService){}
 ngOnInit(){this.sub=this.language.language$.subscribe(()=>void this.load());}ngOnDestroy(){this.sequence++;this.sub?.unsubscribe();}
 t(k:string){return this.data?.labels?.[this.language.currentLanguage]?.[k]||this.data?.labels?.fr?.[k]||k;}
 async load(){const n=++this.sequence;try{const uid=(await this.auth.user()).uid;const data=await firstValueFrom(this.http.get<any>(this.base,{headers:await this.auth.headers()}));if(n!==this.sequence||uid!==(await this.auth.user()).uid)return;this.uid=uid;this.data=data;this.select();}catch{this.error=this.t('error');this.data=null;this.document={};}}
 select(){this.editor++;this.document={...(this.data?.draft?.documents?.[this.role]?.[this.lang]||{})};this.file=undefined;this.reviewed=false;this.confirmed=false;}
 async run(fn:()=>Promise<any>,refresh=true){if(this.busy)return;this.busy=true;this.error='';this.message='';try{if((await this.auth.user()).uid!==this.uid)throw Error('identity_changed');await fn();if(refresh){await this.load();this.message=this.t('success');}}catch(e:any){this.error=this.t(e.status===409?'changed':'error')+(e?.error?.error?' ('+e.error.error+')':'');if(e.status===409)await this.load();}finally{this.busy=false;}}
 resume(){void this.run(async()=>firstValueFrom(this.http.post(this.base+'/resume-active',{revision:this.data.revision},{headers:await this.auth.headers()})));}
 create(){void this.run(async()=>firstValueFrom(this.http.post(this.base+'/draft',{revision:this.data.revision},{headers:await this.auth.headers()})));}
 async choose(event:Event){const input=event.target as HTMLInputElement,f=input.files?.[0],editor=this.editor;input.value='';if(!f)return;if(f.size>6291456||! /\.(pdf|txt|md)$/i.test(f.name)){this.error=this.t('formats');return;}this.file=f;this.reviewed=false;if(/\.(txt|md)$/i.test(f.name)){const text=await f.text();if(editor===this.editor)this.document.text=text;}}
 save(){void this.run(async()=>{const body=new FormData();for(const [k,v]of Object.entries({revision:this.data.revision,role:this.role,language:this.lang,title:this.document.title||'',version:this.document.version||'',text:this.document.text||'',reviewed:String(this.reviewed)}))body.append(k,v);if(this.file)body.append('file',this.file);return firstValueFrom(this.http.post(this.base+'/document',body,{headers:await this.auth.headers()}));});}
 publish(){void this.run(async()=>firstValueFrom(this.http.post(this.base+'/publish',{revision:this.data.revision,confirmed:this.confirmed},{headers:await this.auth.headers()})));}
 previewPdf(){void this.run(async()=>{const blob=await firstValueFrom(this.http.get(this.base+'/file/'+this.role+'/'+this.lang,{headers:await this.auth.headers(),responseType:'blob'}));if((await this.auth.user()).uid!==this.uid)throw Error('identity_changed');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=this.document.attachment?.filename||'conditions.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},false);}
}
